SELECT COALESCE(SUM(CASE WHEN direction = 'in' THEN amount ELSE 0 END), 0) AS inSum,
       COALESCE(SUM(CASE WHEN direction = 'out' THEN amount ELSE 0 END), 0) AS outSum
FROM saving_record
WHERE family_id = #{familyId}
  AND date >= #{start}
  AND date <= #{end}
AND account_id = #{accountId}
